for(const sr of [44100,48000]){
 const a=new current.Engine(sr),b=new old.Engine(sr);for(const e of[a,b]){e.configure({...current.defaultState(),rhythm:4});e.message({type:'drums',on:true});}const l=new Float32Array(128),r=new Float32Array(128),x=new Float32Array(128),y=new Float32Array(128);for(let n=0;n<sr*2;n+=128){a.process(l,r);b.process(x,y);assert.deepEqual(l,x);assert.deepEqual(r,y);}tests.push(sr+': unmuted drums are bit-identical to V0.4.4');
 for(let lane=0;lane<7;lane++){const e=new current.Engine(sr);e.drumEnv.fill(.8);e.drumPitch.fill(1);for(let n=0;n<100;n++)e.drumSample();const before=e.drumMute[lane],mutes=Array(7).fill(false);mutes[lane]=true;e.configure({drumMutes:mutes});assert.equal(e.drumMute[lane],before);e.drumSample();assert.ok(e.drumMute[lane]>.99&&e.drumMute[lane]<1);for(let n=0;n<sr*.1;n++)e.drumSample();assert.equal(e.drumMute[lane],0);for(let i=0;i<7;i++)if(i!==lane)assert.equal(e.drumMute[i],1);mutes[lane]=false;e.configure({drumMutes:mutes});for(let n=0;n<sr*.1;n++)e.drumSample();assert.equal(e.drumMute[lane],1);metrics.push({sr,lane,fadeTimeConstantMs:4});}tests.push(sr+': all seven mutes fade smoothly and independently in both directions');
}writeResults('track-mutes',tests,{metrics});console.log(tests);
